import numpy as npimport matplotlib.pyplot as pltfs = 1200T = 1t = np.arange(0,T,1/fs)m = 2*np.sin(2*np.pi*30*t)+ 4*np.cos(2*np.pi*60*t)delta = 0.5#encoderbits = np.zeros(len(m),dtype = int)reconstructed = np.zeros_like(m)reconstructed[0] = m[0]for n in range(1,len(m)):    if m[n]>=reconstructed[n-1]:        bits[n]=1        reconstructed[n]=reconstructed[n-1]+delta    else:        bits[n]=0        reconstructed[n]=reconstructed[n-1]-delta#decoderdecoded = np.zeros_like(m)decoded[0] = reconstructed[0]for n in range(1,len(m)):     if bits[n]==1:        decoded[n]=decoded[n-1]+delta    else:        decoded[n]=decoded[n-1]-deltadm_mse = np.mean((m-decoded)**2)print("Delta Modulation MSE = ",dm_mse)plt.figure(figsize=(10, 5))plt.plot(t[:50], m[:50], label="Original Signal")plt.step(t[:50], reconstructed[:50], where="mid", label="DM Reconstructed")plt.xlabel("Time")plt.ylabel("Amplitude")plt.title("DM Reconstruction")plt.legend()plt.grid()plt.show()